/* Renovation story: a controllable, motion-led six-frame concept sequence. */
.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.film{background:#f4f8f8}
.film-header{margin-bottom:25px}
.film-shell{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(270px,1fr);gap:1px;overflow:hidden;border:1px solid #254a60;border-radius:13px;background:#1a3e53;box-shadow:0 14px 50px #122e421a}
.film-media{min-width:0;align-self:start;background:#0b2036}
.film-frame{position:relative;aspect-ratio:1.5;background:#122e42;overflow:hidden;isolation:isolate}
.film-shot{position:absolute;inset:0;opacity:0;pointer-events:none;transition:opacity .28s ease;transform:translateZ(0);will-change:opacity}
.film-shot.on{opacity:1;z-index:1;animation:film-pan var(--shot-time,3s) ease-out both;animation-play-state:paused}
.film-frame.playing .film-shot.on{animation-play-state:running}
@keyframes film-pan{from{transform:scale(1.015) translateX(-.25%)}to{transform:scale(1.066) translateX(.4%)}}
.film-image{width:100%;height:100%;object-fit:cover}
.film-shot::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(0deg,#081b31b3,transparent 25%)}
.film-decal{position:absolute;z-index:1;display:block;opacity:.94;pointer-events:none;line-height:0}
.film-decal img{height:auto;object-fit:contain;filter:contrast(1.05) saturate(1.03)}
.decal-ute{left:42.8%;top:73.2%;width:12.1%;transform:rotate(.2deg)}
.decal-truck{left:62.2%;top:45.6%;width:22%;transform:rotate(1deg)}
.film-badge{position:absolute;z-index:2;top:13px;left:13px;display:flex;align-items:center;gap:7px;padding:6px 8px;background:#081b31e9;color:white;border-radius:4px;font-size:.74rem;letter-spacing:.08em;font-weight:780}
.film-badge span{background:#58e4db;width:6px;height:6px;border-radius:50%}
.film-cover-play{position:absolute;z-index:3;inset:50% auto auto 50%;transform:translate(-50%,-50%);display:grid;place-items:center;width:68px;height:68px;border:2px solid #b4fbf2;border-radius:50%;color:#0b2a36;background:#66e7dcec;box-shadow:0 5px 33px #06172a73}
.film-cover-play:hover{background:#b4fff4}
.film-cover-play[hidden]{display:none}
.film-cover-play svg{width:26px;height:26px;fill:currentColor;stroke:none}
.film-overlay{position:absolute;left:14px;bottom:13px;z-index:2;color:white;display:flex;gap:9px;align-items:center;text-shadow:0 2px 10px #082036;pointer-events:none}
.film-overlay span{font-size:.8rem;letter-spacing:.1em;font-weight:800;color:#a1f6ed}
.film-overlay strong{font-size:1.1rem}
.film-control{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:11px;padding:9px 12px;color:#e4f3fc}
.film-control button{background:#183a54;color:#fff;border:1px solid #6896ac;min-height:38px;min-width:87px;border-radius:6px;padding:5px 8px;font-weight:740}
.film-control button:hover{background:#2d546d}
.film-control input{width:100%;min-width:0;accent-color:#63e8de;cursor:pointer}
.film-control>span{font-size:.8rem;font-variant-numeric:tabular-nums;white-space:nowrap}
.film-narrative{padding:23px;color:#fff;background:radial-gradient(ellipse at 80% 100%,#163c4d,#0b233d 69%);display:flex;flex-direction:column}
.film-kicker{font-size:.76rem;font-weight:800;letter-spacing:.1em;color:#87f3e6;margin-bottom:10px}
.film-narrative h3{font-size:clamp(1.55rem,3vw,2.9rem);margin-bottom:7px}
.film-narrative>p:not(.film-kicker){color:#d5e7f1;min-height:4.4em}
.film-chapters{list-style:none;margin:15px 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:7px}
.film-chapters button{width:100%;display:flex;gap:7px;align-items:center;min-height:39px;text-align:left;color:#edf8ff;background:#163b55;border:1px solid #4a7287;border-radius:5px;padding:5px 7px;font-size:.87rem}
.film-chapters button span{font-size:.74rem;color:#a4d4e1}
.film-chapters button[aria-pressed=true],.film-chapters button:hover{color:#072e36;background:#8cf2e7;border-color:#8cf2e7}
.film-chapters button[aria-pressed=true] span,.film-chapters button:hover span{color:#18666b}
.film-narrative>a{margin-top:6px;color:#a1f8ed;text-underline-offset:4px;font-size:.88rem;font-weight:740}
.film-disclaimer{color:#587083;font-size:.84rem;margin-top:10px}
.finish-sparks{position:absolute;inset:0;display:block;pointer-events:none;z-index:2}
.finish-sparks i{position:absolute;opacity:0;width:23px;height:23px;background:#eefdfc;clip-path:polygon(50% 0,59% 39%,100% 50%,59% 61%,50% 100%,41% 61%,0 50%,41% 39%);filter:drop-shadow(0 0 5px #fff)}
.finish-sparks i:nth-child(1){top:49%;left:63%}
.finish-sparks i:nth-child(2){top:64%;left:78%;width:14px;height:14px}
.finish-sparks i:nth-child(3){top:38%;left:50%;width:14px;height:14px}
.film-frame.playing .film-shot.on .finish-sparks i{animation:finish-shine 1.2s ease-in-out .35s 1 both}
.film-frame.playing .film-shot.on .finish-sparks i:nth-child(2){animation-delay:.5s}
.film-frame.playing .film-shot.on .finish-sparks i:nth-child(3){animation-delay:.63s}
@keyframes finish-shine{0%,100%{transform:scale(.2) rotate(-15deg);opacity:0}45%{transform:scale(1.13) rotate(8deg);opacity:.9}}
.craft{background:#eaf3f3}
.craft-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}
