@media(max-width:980px){.craft-card{grid-template-columns:1fr}.craft-card img{aspect-ratio:1.85;min-height:0;height:auto}}
@media(max-width:820px){.film-shell{grid-template-columns:1fr}.film-narrative{padding:17px}.film-narrative>p:not(.film-kicker){min-height:0}.film-chapters{grid-template-columns:repeat(3,minmax(0,1fr))}.film-narrative>a{margin-top:0}}
@media(max-width:450px){.film-chapters{grid-template-columns:repeat(2,minmax(0,1fr))}.film-control{gap:5px;padding:7px}.film-control button{min-width:73px;font-size:.8rem}.film-badge{font-size:.62rem}.film-cover-play{width:52px;height:52px}.craft-grid{grid-template-columns:1fr}}
