/* Hero transformation wall and trade-direct proof points. */
.hero-inner{grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr)}
.hero-mosaic{min-width:0;border-radius:13px;padding:13px;border:1px solid #487786;background:linear-gradient(152deg,#17354b,#0c243a 70%);box-shadow:0 13px 32px #06162b6b;isolation:isolate}
.mosaic-titlebar,.mosaic-footer,.mosaic-titlebar>div,.mosaic-controls{display:flex;align-items:center;justify-content:space-between;gap:10px}
.mosaic-titlebar{padding:0 0 10px}
