.dock-actions{grid-template-columns:1.07fr .95fr 1.08fr}
.dock-actions .dock-price{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;background:#183e51;border-color:#65aaa8;color:#a3fbef;line-height:1.1}
.dock-price strong{font-size:inherit}
.dock-price small{font-size:.68rem;color:#cfe7ed;white-space:nowrap}
.dock-actions .dock-price:hover{background:#205367;border-color:#95ede2}
@media(max-width:820px){.project-dock{width:min(397px,calc(100vw - 24px))}}
@media(max-width:560px){.project-dock{width:auto}.dock-actions a{font-size:clamp(.7rem,2.7vw,.85rem);padding-inline:2px}.dock-price small{font-size:clamp(.56rem,2vw,.68rem)}}

/* On-site trade work and the people behind the operation. */
.on-site{background:#edf5f5}
.crew-feature{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);overflow:hidden;border-radius:12px;border:1px solid #426579;background:#0d2841}
.crew-photo{position:relative;aspect-ratio:1.5;isolation:isolate;overflow:hidden}
.crew-photo>img{height:100%;width:100%;object-fit:cover}
.crew-photo figcaption{position:absolute;left:12px;bottom:12px;padding:5px 8px;background:#081b31e8;color:#eefcff;border-radius:4px;font-size:.74rem;font-weight:800;letter-spacing:.075em}
.crew-decal{position:absolute;z-index:1;display:block;line-height:0;pointer-events:none;opacity:.94}
.crew-decal img{height:auto;object-fit:contain}
.crew-truck{left:64%;top:22%;width:23%;transform:rotate(2.2deg)}
.crew-ute{left:70.1%;top:48.5%;width:5.7%;transform:rotate(-1.4deg)}
.crew-copy{align-self:center;color:#fff;padding:clamp(18px,4vw,48px)}
.crew-copy .eyebrow{color:#83f3e7;font-size:.75rem}
.crew-copy h3{font-size:clamp(1.8rem,3.65vw,3.58rem);line-height:1.01;margin-top:12px}
.crew-copy>p:not(.eyebrow){color:#d5e6f0;margin:12px 0 16px}
.crew-copy>.button{white-space:normal}
.trade-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:12px}
.trade-gallery>article{min-width:0;background:#fff;border:1px solid #d3e1e6;border-radius:9px;overflow:hidden}
.trade-gallery img{aspect-ratio:1.62}
.trade-gallery>article>div{padding:14px}
.trade-gallery h3{font-size:clamp(1.28rem,2.05vw,1.82rem);margin-bottom:6px}
.trade-gallery p{color:#405869}
.trade-gallery a{display:inline-block;margin-top:9px;color:#155b68;text-underline-offset:4px;font-size:.88rem;font-weight:800}
.team-disclaimer{margin-top:10px;color:#536c7b;font-size:.84rem}
.people{background:linear-gradient(118deg,#0a2037,#112d46);color:#fff}
.people .eyebrow{color:#85f4e7}
.people .section-head>p{color:#d4e4ed}
.people-placeholder{display:flex;align-items:center;gap:7px;color:#c8dfe7;font-size:.86rem;margin:-3px 0 12px}
.people-placeholder span{width:6px;height:6px;flex:none;transform:rotate(45deg);background:#8ff0e5}
.people-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.person-card{min-width:0;overflow:hidden;background:#f8fbfb;color:#0b253d;border:1px solid #537285;border-radius:10px}
.person-card figure{position:relative;aspect-ratio:1;overflow:hidden;background:#c9d6d9}
.person-card figure>img:first-child{height:100%;width:100%;object-fit:cover}
.person-card .shirt-logo{position:absolute;left:var(--shirt-x,59%);top:var(--shirt-y,80%);width:var(--shirt-w,21%);height:auto;object-fit:contain;opacity:.88;transform:rotate(var(--shirt-r,0deg));filter:drop-shadow(0 .35px .3px #0b1829)}
.person-card>div{padding:14px}
.person-card .person-role{font-size:.81rem;color:#0a716a;font-weight:800}
.person-card h3{font-size:clamp(1.32rem,2.3vw,2rem);margin:4px 0 7px}
.person-card p:not(.person-role){color:#435969;font-size:.93rem}
.people-next{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:15px;padding:12px 14px;border:1px solid #496b7d;background:#15364e;border-radius:8px;color:#dcecf3}
