.people-next .button:hover{background:#a7f8ef}
@media(max-width:820px){.crew-feature{grid-template-columns:1fr}.crew-copy{padding:18px}.crew-photo{aspect-ratio:1.5}.people-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.trade-gallery{gap:8px}.trade-gallery>article>div,.person-card>div{padding:10px}}
@media(max-width:540px){.trade-gallery{grid-template-columns:1fr}.trade-gallery img{aspect-ratio:1.75}.people-grid{gap:8px}.person-card p:not(.person-role){font-size:.83rem}.person-card .person-role{font-size:.72rem}.people-next{align-items:flex-start;flex-direction:column}.people-next .button{width:100%}}
.person-daniel{--shirt-x:61.1%;--shirt-y:75.5%;--shirt-w:18.8%;--shirt-r:-.6deg}
.person-luke{--shirt-x:61.5%;--shirt-y:76.6%;--shirt-w:18.8%;--shirt-r:1.1deg}
.person-sophie{--shirt-x:61%;--shirt-y:76.5%;--shirt-w:18.8%;--shirt-r:-.4deg}
.person-amelia{--shirt-x:62%;--shirt-y:76.8%;--shirt-w:18.8%;--shirt-r:.5deg}

/* Nifty build additions: site menu, keyword intro, areas, FAQ, content links. */
@media(max-width:420px){.brand{width:min(200px,58vw)}.nav-row{gap:10px}.menu{padding:6px 10px}}
.hero h1 .h1-lead{display:block;font-size:clamp(1.05rem,1.7vw,1.4rem);letter-spacing:-.01em;line-height:1.2;font-weight:800;color:#9ff6ed;margin-bottom:16px}
main p a:not(.button):not(.studio-open),main li a:not(.button),.faq-a a{color:#0b6f68;text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px;font-weight:700}
main p a:not(.button):not(.studio-open):hover,main li a:not(.button):hover,.faq-a a:hover{color:#063f4a;text-decoration-thickness:2px}
main .svc-feature li a:not(.button){color:#a1fbf2}
main .svc-feature li a:not(.button):hover{color:#ffffff}
.idea-sources a{font-weight:400}
.svc li{margin:5px 0}
.svc-more,.gallery-real{margin-top:18px;color:var(--muted);font-size:1.02rem}
.intro{background:#fff}
.intro-grid,.areas-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:48px;align-items:start}
.intro-copy p,.areas-copy p{color:var(--muted);font-size:1.08rem;margin-bottom:15px;max-width:660px}
.areas{background:#f1f5f5}
.area-list{list-style:none;padding:0;margin:4px 0 18px;display:flex;flex-wrap:wrap;gap:8px}
.area-list li{border:1px solid #c6d8de;background:#fff;border-radius:6px;padding:8px 13px;font-weight:750;font-size:.93rem}
.faq{background:#fff}
.faq-grid{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.4fr);gap:48px;align-items:start}
.faq-intro{position:sticky;top:20px}
.faq-intro p:not(.eyebrow){color:var(--muted);margin-top:16px;font-size:1.06rem;max-width:380px}
.faq-list details{border-top:1px solid var(--line);padding:15px 0}
