.faq-list summary::-webkit-details-marker{display:none}
.faq-list summary h3{font-size:clamp(1.12rem,1.65vw,1.38rem);letter-spacing:-.02em;line-height:1.22}
.faq-list summary::after{content:"+";flex:none;font-size:1.55rem;font-weight:700;color:#08766e;line-height:1}
.faq-list details[open] summary::after{content:"\2212"}
.faq-a p{color:var(--muted);margin-top:10px;max-width:720px}
.person-card figure{background:#d7e3e6}
.send-card{margin-top:12px}
#brief-send{display:none!important}
