/* ===== Mega menu: shared ===== */
.header{position:relative;z-index:50;background:#fff}
.nav-toggle,.sub-toggle{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.nav-list{list-style:none;margin:0;padding:0}
.drawer-head,.drawer-foot,.nav-scrim,.sub-label,.drawer-close{display:none}
#nav a{text-decoration:none}
#nav .mega-feature,#nav .mega-feature *{white-space:normal}
.mega-head{display:flex;align-items:center;gap:8px;margin:0 0 8px;padding-bottom:9px;border-bottom:1px dashed #a9d2cc;font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;font-weight:800;color:#08766e}
.mega-head svg{width:19px;height:19px;flex:none;padding:3px;box-sizing:content-box;border-radius:6px;background:#e1f6f2;color:#08766e;stroke-width:1.9}
