#nav .mlink::before{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:linear-gradient(100deg,#e3f8f4 0%,#c9f3ec 100%);box-shadow:inset 3px 0 0 #08766e;transform:translateX(-102%);transition:transform .38s cubic-bezier(.2,.8,.2,1)}
#nav .mlink::after{content:"\2192";margin-left:auto;font-weight:800;color:#08766e;opacity:0;transform:translateX(-10px);transition:opacity .25s,transform .3s}
#nav .mlink:hover,#nav .mlink:focus-visible{color:#05434c;padding-left:17px;outline:none}
#nav .mlink:hover::before,#nav .mlink:focus-visible::before{transform:none}
#nav .mlink:hover::after,#nav .mlink:focus-visible::after{opacity:1;transform:none}
#nav .mlink.lead{margin-bottom:4px}
