#nav .mlink.lead small{display:block;margin-top:2px;font-size:.78rem;font-weight:500;color:#4b6475}
.mega-feature{position:relative;display:flex;flex-direction:column;align-self:start;border-radius:14px;overflow:hidden;background:#081b31;color:#fff;text-decoration:none;box-shadow:0 14px 30px #081b3138;transition:transform .45s cubic-bezier(.2,.8,.2,1),box-shadow .45s}
.mega-feature:hover,.mega-feature:focus-visible{transform:translateY(-5px) rotate(-.5deg);box-shadow:0 24px 44px #081b314d}
.mf-media{position:relative;display:block;aspect-ratio:1.55;overflow:hidden;background:#17324a}
.mf-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform 1.2s ease}
.mega-feature:hover .mf-media img{transform:scale(1.05)}
.mf-after{clip-path:inset(0 0 0 100%);transition:clip-path 1s cubic-bezier(.77,0,.18,1) .25s,transform 1.2s ease!important}
.mf-line{position:absolute;top:0;bottom:0;left:100%;width:3px;margin-left:-1.5px;background:#62f0e4;box-shadow:0 0 14px #51e4d8,0 0 3px #fff;transition:left 1s cubic-bezier(.77,0,.18,1) .25s,opacity .3s}
.mf-tag{position:absolute;top:9px;z-index:1;padding:3px 7px;border-radius:4px;font-size:.66rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
.mf-b{left:9px;background:#081b31e6;color:#fff}.mf-a{right:9px;background:#9bf4e9;color:#0b2d33}
.mf-body{display:grid;gap:5px;padding:14px 16px 16px;background:radial-gradient(ellipse at 100% 100%,#164b58,#0b243c 70%)}
.mf-kicker{font-size:.7rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#7ef1e5}
.mf-title{font-size:1.2rem;font-weight:850;letter-spacing:-.03em;line-height:1.12}
.mf-cta{display:inline-flex;align-items:center;gap:7px;margin-top:4px;font-size:.86rem;font-weight:750;color:#a5fbf1}
.mf-cta i,.mega-brief i,.mega-all i{font-style:normal;transition:transform .3s cubic-bezier(.34,1.56,.64,1)}
.mega-feature:hover .mf-cta i,.mega-brief:hover i{transform:translateX(5px)}
.mega-feature:hover .mf-after{clip-path:inset(0 0 0 0);transition-delay:0s}
.mega-feature:hover .mf-line{left:0;opacity:0;transition-delay:0s,.9s}
.burger{position:relative;display:inline-block;width:18px;height:14px;margin-right:9px}
.burger i{position:absolute;left:0;width:100%;height:2px;border-radius:2px;background:currentColor;transition:transform .35s cubic-bezier(.77,0,.18,1),opacity .2s,top .35s}
.burger i:nth-child(1){top:0}.burger i:nth-child(2){top:6px}.burger i:nth-child(3){top:12px}
.nav-toggle:focus-visible+.menu{outline:3px solid #16a89c;outline-offset:3px}

