 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-tape,.nav-item:has(:focus-visible) .mega-tape{transform:scaleX(1)}
 .mega-inner{position:relative;display:grid;grid-template-columns:minmax(250px,300px) minmax(0,1fr);gap:clamp(20px,2.2vw,34px);padding:28px 0 20px}
 .mega[data-cols="1"] .mega-inner{grid-template-columns:minmax(250px,320px) minmax(0,420px)}
 .mega[data-cols="2"] .mega-inner{grid-template-columns:minmax(250px,320px) minmax(0,640px)}
 .mega-cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px clamp(14px,1.6vw,26px);align-content:start}
 .mega-feature,.mega-col{opacity:0;transform:translateY(16px);transition:opacity .45s,transform .55s cubic-bezier(.2,.8,.2,1)}
 .mega-feature{transform:translateX(-18px) translateY(0)}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-feature,.nav-item:has(:focus-visible) .mega-feature,.nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-col,.nav-item:has(:focus-visible) .mega-col{opacity:1;transform:none}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-feature:hover{transform:translateY(-5px) rotate(-.5deg)}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-feature{transition-delay:.12s}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-col:nth-child(1){transition-delay:.18s}.nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-col:nth-child(2){transition-delay:.25s}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-col:nth-child(3){transition-delay:.32s}.nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-col:nth-child(4){transition-delay:.39s}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mf-after,.nav-item:has(:focus-visible) .mf-after{clip-path:inset(0 0 0 50%)}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mf-line,.nav-item:has(:focus-visible) .mf-line{left:50%}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-feature:hover .mf-after{clip-path:inset(0 0 0 0)}
 .nav-item:is(.is-open,:hover:not(.mm-js *)) .mega-feature:hover .mf-line{left:0;opacity:0}
 .mega-foot{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 0 20px;border-top:1px solid #dfeaed;font-size:.88rem;color:#3d5668}
 .mega-all{display:inline-flex;align-items:center;gap:8px;font-weight:800;color:#08766e!important;text-decoration:none}
 .mega-all:hover i{transform:translateX(5px)}
 .mega-note{margin-left:auto}
 .mega-brief{display:inline-flex;align-items:center;gap:8px;padding:9px 14px;border-radius:7px;background:#081b31;color:#fff;font-weight:750;text-decoration:none;transition:background .25s}
 .mega-brief:hover{background:#0b5f5a}
 .menu{display:none!important}
}
@keyframes mm-shimmer{from{background-position:0 0}to{background-position:250% 0}}

/* ===== Tablet and mobile drawer ===== */
@media (max-width:1180px),(hover:none) and (pointer:coarse){
 .nav-row{position:relative}
 .menu{display:inline-flex!important;align-items:center;cursor:pointer;color:var(--ink);border:1px solid #a9bdc8;background:#fff;border-radius:7px;min-height:44px;padding:6px 13px;font-weight:750;margin-left:auto;transition:background .25s,border-color .25s}
 .menu:hover{background:#eef8f6;border-color:#08766e}
 .nav-toggle:checked+.menu .burger i:nth-child(1){top:6px;transform:rotate(45deg)}
 .nav-toggle:checked+.menu .burger i:nth-child(2){opacity:0;transform:scaleX(.2)}
 .nav-toggle:checked+.menu .burger i:nth-child(3){top:6px;transform:rotate(-45deg)}
 .nav-scrim{display:block;position:fixed;inset:0;z-index:80;background:#06172ab3;backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);opacity:0;pointer-events:none;transition:opacity .4s;cursor:pointer}
 .nav-toggle:checked~.nav-scrim{opacity:1;pointer-events:auto}
 #nav{position:fixed;top:0;right:0;bottom:0;left:auto;z-index:90;display:flex;flex-direction:column;align-items:stretch;gap:0;width:min(460px,92vw);max-height:none;padding:0;overflow-y:auto;overscroll-behavior:contain;border:0;border-radius:18px 0 0 18px;
  background-color:#fbfefe;background-image:linear-gradient(#08766e0a 1px,transparent 1px),linear-gradient(90deg,#08766e0a 1px,transparent 1px);background-size:28px 28px;
  box-shadow:-24px 0 60px #06172a59;transform:translateX(105%);visibility:hidden;transition:transform .55s cubic-bezier(.77,0,.18,1),visibility 0s linear .55s}
 .nav-toggle:checked~#nav{transform:none;visibility:visible;transition-delay:0s}
 .drawer-head{display:flex;align-items:center;justify-content:space-between;gap:12px;position:sticky;top:0;z-index:3;padding:14px 18px;background:#ffffffeb;backdrop-filter:blur(6px);border-bottom:1px solid #e1ebee}
 .drawer-head img{width:170px;height:auto}
 .drawer-close{display:grid;place-items:center;width:44px;height:44px;border-radius:10px;background:#081b31;cursor:pointer;transition:transform .35s cubic-bezier(.34,1.56,.64,1),background .25s}
 .drawer-close::before{content:"\00d7";color:#fff;font-size:1.7rem;line-height:1;font-weight:500}
 .drawer-close:hover{transform:rotate(90deg);background:#08766e}
 .nav-list{display:block;padding:6px 18px 14px}
 .nav-item{position:relative;border-bottom:1px solid #e3ecee;opacity:0;transform:translateX(30px);transition:opacity .4s,transform .5s cubic-bezier(.2,.8,.2,1)}
 .nav-toggle:checked~#nav .nav-item{opacity:1;transform:none}
 .nav-toggle:checked~#nav .nav-item:nth-child(1){transition-delay:.12s}.nav-toggle:checked~#nav .nav-item:nth-child(2){transition-delay:.17s}
 .nav-toggle:checked~#nav .nav-item:nth-child(3){transition-delay:.22s}.nav-toggle:checked~#nav .nav-item:nth-child(4){transition-delay:.27s}
 .nav-toggle:checked~#nav .nav-item:nth-child(5){transition-delay:.32s}.nav-toggle:checked~#nav .nav-item:nth-child(6){transition-delay:.37s}
 .nav-toggle:checked~#nav .nav-item:nth-child(7){transition-delay:.42s}.nav-toggle:checked~#nav .nav-item:nth-child(8){transition-delay:.47s}
 #nav .nav-top{display:flex;align-items:center;gap:8px;padding:16px 56px 16px 2px;font-size:1.08rem;font-weight:800;color:var(--ink);text-decoration:none;white-space:normal}
 .nt-chev{display:none}
 .sub-label{display:grid;place-items:center;position:absolute;right:0;top:9px;width:44px;height:44px;border-radius:11px;background:#e6f6f2;cursor:pointer;transition:background .25s}
 .sub-label::before{content:"+";font-size:1.55rem;font-weight:600;line-height:1;color:#08766e;transition:transform .4s cubic-bezier(.34,1.56,.64,1)}
 .sub-toggle:checked+.sub-label{background:#081b31}
 .sub-toggle:checked+.sub-label::before{transform:rotate(135deg);color:#7ef1e5}
 .sub-toggle:focus-visible+.sub-label{outline:3px solid #16a89c;outline-offset:2px}
 .mega{display:grid;grid-template-rows:0fr;transition:grid-template-rows .5s cubic-bezier(.77,0,.18,1)}
 .sub-toggle:checked~.mega{grid-template-rows:1fr}
 .mega-clip{min-height:0;overflow:hidden}
 .mega-tape,.mega-foot{display:none}
 .mega-inner{display:grid;gap:14px;width:auto;padding:2px 0 18px}
 .mega-feature{flex-direction:row;border-radius:12px}
 .mf-media{flex:0 0 42%;aspect-ratio:auto;min-height:118px}
 .mf-after{clip-path:inset(0 0 0 50%)}
 .mf-line{left:50%}
 .mf-tag{font-size:.6rem;top:7px;padding:2px 5px}.mf-b{left:6px}.mf-a{right:6px}
 .mf-body{align-content:center;padding:12px 14px}
 .mf-title{font-size:1.02rem}
 .mega-cols{display:grid;grid-template-columns:1fr;gap:14px}
 .mega-head{margin-top:2px}
 #nav .mlink{padding:10px 10px 10px 12px;font-size:.95rem}
 .drawer-foot{display:grid;gap:10px;margin-top:auto;padding:18px 18px 26px;background:radial-gradient(ellipse at 100% 100%,#164b58,#081b31 70%);color:#cfe3ec;font-size:.85rem}
 .drawer-foot .button{width:100%}
 body:has(.nav-toggle:checked){overflow:hidden}
 body:has(.nav-toggle:checked) .project-dock{display:none}
}
@media (min-width:560px) and (max-width:1180px){.mega-cols{grid-template-columns:1fr 1fr}}
@media (max-width:600px){.nav-cta{display:none}.top-inner>span:last-child{display:none}}
@media (max-width:420px){.brand{width:min(200px,56vw)}.nav-row{gap:10px}.menu{padding:6px 10px}.menu-text{font-size:.92rem}}
@media (prefers-reduced-motion:reduce){.mega,.mega *,#nav,#nav *,.nav-scrim{transition-duration:.01s!important;animation:none!important;transition-delay:0s!important}}
